import test from 'node:test';
import assert from 'node:assert/strict';
import {mkdtempSync, writeFileSync, rmSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {normalizeSegments, resolveWithin, cli} from '../path-scope.js';

test('lexical resolution respects normalized segment boundaries',()=>{
  const cases=[
    ['/srv/ws','../ws/sub/../file.txt',true,'/srv/ws/file.txt','file.txt'],
    ['/a/b','/a/bc',false,'/a/bc',null],
    ['/a/b','../../..',false,'/',null],
    ['/a//b/../','./',true,'/a',''],
    ['/../../','../../../x//./',true,'/x','x'],
    ['/a/b','/a',false,'/a',null],
    ['/a/b','/a/b/../b/',true,'/a/b',''],
    ['/a','..foo/.../.hidden/\\/x',true,'/a/..foo/.../.hidden/\\/x','..foo/.../.hidden/\\/x'],
    ['/a/../b','../b/c',true,'/b/c','c']
  ];
  for(const [root,candidate,inside,resolved,relative] of cases){
    assert.deepEqual(resolveWithin(root,candidate),{inside,resolved,relative});
  }
});

test('input validation does not change the existing helper contract',()=>{
  for(const value of ['',null,undefined,0,false,[],{},'/a\0b']){
    assert.throws(()=>resolveWithin(value,'x'),Error);
    assert.throws(()=>resolveWithin('/a',value),Error);
  }
  assert.throws(()=>resolveWithin('relative','/a'),Error);
  assert.deepEqual(normalizeSegments(''),[]);
  assert.deepEqual(normalizeSegments('a\0b'),['a\0b']);
  assert.equal(typeof cli,'function');
});

const moduleURL=new URL('../path-scope.js',import.meta.url);
const run=(args)=>spawnSync(process.execPath,[fileURLToPath(moduleURL),...args],{encoding:'utf8'});

test('CLI emits exactly one result and rejects invalid files and inputs',()=>{
  const dir=mkdtempSync(join(tmpdir(),'path-scope-'));
  try{
    const file=join(dir,'input.json');
    writeFileSync(file,JSON.stringify({root:'/srv/ws',candidate:'../ws/file.txt',extra:123}));
    const success=run([file]);
    assert.equal(success.status,0);
    assert.equal(success.stderr,'');
    assert.equal(success.stdout,'{"inside":true,"resolved":"/srv/ws/file.txt","relative":"file.txt"}\n');
    const reject=(args)=>{
      const result=run(args);
      assert.equal(result.status,2);
      assert.equal(result.stdout,'');
      assert.ok(result.stderr.length>0);
    };
    reject([]);
    reject([file,file]);
    reject([join(dir,'missing.json')]);
    reject([dir]);
    for(const contents of ['{','null','[]','42','"text"','{}',
      '{"root":"a","candidate":"b"}',
      '{"root":"/a","candidate":""}',
      '{"root":"/a","candidate":"\\u0000"}']){
      writeFileSync(file,contents);
      reject([file]);
    }
  }finally{
    rmSync(dir,{recursive:true,force:true});
  }
});

test('importing the module is silent and does not run the CLI',()=>{
  const result=spawnSync(process.execPath,['--input-type=module','-e',
    `await import(${JSON.stringify(moduleURL.href)})`],{encoding:'utf8'});
  assert.equal(result.status,0);
  assert.equal(result.stdout,'');
  assert.equal(result.stderr,'');
});

